<script setup>
import { computed,ref } from "vue";
import { useRouter } from "vue-router";
import AuthLayout from "../../layouts/AuthLayout.vue";
import { startTrial } from "../../services/billing.service.js";
import { useAuthStore } from "../../stores/auth.store.js";
import { language,setLanguage } from "../../i18n/index.js";

const router=useRouter();const auth=useAuthStore();const loading=ref(false);const errorMessage=ref("");const showPassword=ref(false);
const form=ref({group_name:"",name:"",email:"",phone:"",password:""});
const completedFields=computed(()=>[form.value.group_name,form.value.name,form.value.email,form.value.password.length>=8].filter(Boolean).length);
const progress=computed(()=>`${completedFields.value/4*100}%`);
const submit=async()=>{loading.value=true;errorMessage.value="";try{const response=await startTrial({...form.value,language:language.value});auth.setAuth(response.data.token,response.data.language,response.data.organization);setLanguage(response.data.language);await router.replace("/");}catch(error){errorMessage.value=error.response?.data?.message||"Unable to start trial.";}finally{loading.value=false;}};
</script>

<template><AuthLayout><main class="onboarding-page">
  <header class="topbar"><router-link class="brand" to="/login"><span>V</span><div><strong>Vikoba</strong><small>Group Finance Platform</small></div></router-link><div class="top-actions"><span>Already have an account?</span><router-link to="/sign-in">Sign in</router-link><label><i class="bi bi-globe2"></i><select :value="language" aria-label="Language" @change="setLanguage($event.target.value)"><option value="en">English</option><option value="sw">Kiswahili</option></select></label></div></header>

  <section class="onboarding-shell"><aside class="value-panel"><div class="value-content"><router-link class="back-link" to="/login"><i class="bi bi-arrow-left"></i> Back to website</router-link><span class="eyebrow">7-day Professional trial</span><h1>Give your group finances a better home.</h1><p>Create one secure workspace for members, money, meetings, approvals, and reports. Set up takes only a few minutes.</p><div class="benefits"><article><i class="bi bi-check2"></i><div><strong>Every feature included</strong><small>Explore the complete platform during your trial.</small></div></article><article><i class="bi bi-credit-card"></i><div><strong>No payment card required</strong><small>Choose a plan only when your group is ready.</small></div></article><article><i class="bi bi-shield-lock"></i><div><strong>Your records remain yours</strong><small>After trial expiry, existing data stays readable.</small></div></article></div></div><div class="trust-card"><div class="avatars"><span>AJ</span><span>MK</span><span>SN</span><span>+20</span></div><p><strong>Built for accountable teams</strong><small>Clear roles, two-person approvals, and a complete audit trail.</small></p></div></aside>

    <section class="form-panel"><div class="form-wrap"><div class="step-row"><div><span>Workspace setup</span><strong>{{ completedFields }} of 4 required details</strong></div><div class="progress-track"><i :style="{width:progress}"></i></div></div><div class="form-heading"><span>Get started free</span><h2>Create your group workspace</h2><p>You will be the workspace owner and can invite other leaders after setup.</p></div>
      <form @submit.prevent="submit"><fieldset><legend><span>1</span> Group information</legend><label for="group-name">Group name<div class="input-wrap"><i class="bi bi-people"></i><input id="group-name" v-model.trim="form.group_name" required autocomplete="organization" placeholder="Example: Umoja Vikoba Group"></div><small>The official name members will recognize.</small></label></fieldset>
        <fieldset><legend><span>2</span> Administrator account</legend><div class="two-columns"><label for="admin-name">Full name<div class="input-wrap"><i class="bi bi-person"></i><input id="admin-name" v-model.trim="form.name" required autocomplete="name" placeholder="Your full name"></div></label><label for="phone">Phone number <em>Optional</em><div class="input-wrap"><i class="bi bi-phone"></i><input id="phone" v-model.trim="form.phone" type="tel" autocomplete="tel" placeholder="+255 7xx xxx xxx"></div></label></div><label for="trial-email">Email address<div class="input-wrap"><i class="bi bi-envelope"></i><input id="trial-email" v-model.trim="form.email" type="email" required autocomplete="email" placeholder="you@example.com"></div></label><label for="trial-password">Create password<div class="input-wrap"><i class="bi bi-lock"></i><input id="trial-password" v-model="form.password" :type="showPassword?'text':'password'" minlength="8" required autocomplete="new-password" placeholder="At least 8 characters"><button type="button" :aria-label="showPassword?'Hide password':'Show password'" @click="showPassword=!showPassword"><i class="bi" :class="showPassword?'bi-eye-slash':'bi-eye'"></i></button></div><small>Use eight or more characters that are difficult to guess.</small></label></fieldset>
        <div v-if="errorMessage" class="error-message" role="alert"><i class="bi bi-exclamation-circle"></i><span>{{ errorMessage }}</span></div><button class="submit-button" :disabled="loading"><span v-if="loading" class="spinner-border spinner-border-sm"></span><span>{{ loading?'Creating your workspace...':'Create workspace and start trial' }}</span><i v-if="!loading" class="bi bi-arrow-right"></i></button></form><p class="terms"><i class="bi bi-lock-fill"></i> Your information is protected. By continuing, you confirm that you are authorized to create and administer this group workspace.</p></div></section>
  </section>
</main></AuthLayout></template>

